package kim.biryeong.destiny.economy;

import com.google.gson.JsonParser;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.FontDescription;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.resources.Identifier;

import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Builds the economy menu titles. The title string carries the Destiny-style chest background as font glyphs
 * (font {@code destiny:econ_gui}, generated by scripts/economy/build_econ_gui.py with the layout in
 * {@code /destiny/economy/gui.json}) followed by the header text in Noto Sans KR ({@code destiny:econ_text}).
 */
final class EconomyGui {
    static final FontDescription.Resource GUI = new FontDescription.Resource(Identifier.fromNamespaceAndPath("destiny", "econ_gui"));
    static final FontDescription.Resource TEXT = new FontDescription.Resource(Identifier.fromNamespaceAndPath("destiny", "econ_text"));
    /** Header text starts here (GUI px from the chest's left edge), right of the baked header icon. */
    static final int HEADER_X = 18;
    private static final int ORIGIN_X, TILE, TITLE_X;
    private static final Map<String, List<String>> ROWS = new HashMap<>();

    static {
        try (var in = EconomyGui.class.getResourceAsStream("/destiny/economy/gui.json")) {
            var root = JsonParser.parseReader(new InputStreamReader(Objects.requireNonNull(in), StandardCharsets.UTF_8)).getAsJsonObject();
            ORIGIN_X = root.get("originX").getAsInt(); TILE = root.get("tile").getAsInt(); TITLE_X = root.get("titleX").getAsInt();
            for (var e : root.getAsJsonObject("screens").entrySet()) {
                var rows = new ArrayList<String>();
                for (var row : e.getValue().getAsJsonArray()) {
                    var sb = new StringBuilder();
                    for (var cp : row.getAsJsonArray()) sb.append(cp.getAsString());
                    rows.add(sb.toString());
                }
                ROWS.put(e.getKey(), List.copyOf(rows));
            }
        } catch (Exception e) { throw new IllegalStateException("Unreadable destiny/economy/gui.json", e); }
    }

    private EconomyGui() { }

    /** Font space glyphs moving the cursor by {@code px} (any sign); U+E100+k = -2^k, U+E120+k = +2^k. */
    static String space(int px) {
        var sb = new StringBuilder();
        int base = px < 0 ? 0xE100 : 0xE120; int v = Math.abs(px);
        for (int k = 8; k >= 0; k--) while (v >= (1 << k)) { sb.appendCodePoint(base + k); v -= 1 << k; }
        return sb.toString();
    }

    /**
     * Title for screen {@code id} (vault, mail, auction, sell, send, confirm, listings): background tiles, then
     * {@code header} in white Noto. Each bitmap glyph advances its width + 1, corrected per tile.
     */
    static Component title(String id, String header) {
        var rows = ROWS.get(id);
        var bg = new StringBuilder(space(ORIGIN_X - TITLE_X));
        int width = 0;
        for (String row : rows) {
            for (int i = 0; i < row.length(); i++) bg.append(row.charAt(i)).append(space(-1));
            width = row.length() * TILE;
            bg.append(space(-width));
        }
        // cursor is back at ORIGIN_X; move to the header position
        bg.append(space(HEADER_X - ORIGIN_X));
        MutableComponent out = Component.literal(bg.toString()).withStyle(Style.EMPTY.withFont(GUI).withColor(0xFFFFFF));
        out.append(Component.literal(header).withStyle(Style.EMPTY.withFont(TEXT).withColor(0xE6EAEE)));
        return out;
    }

    static Style text(int color) { return Style.EMPTY.withFont(TEXT).withColor(color).withItalic(false); }
}
